// Web'den servo: sayfadaki kaydırıcı servonun açısını ayarlar.
#include <WiFi.h>
#include <WebServer.h>
#include <ESP32Servo.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
const int SERVO_PIN = 18;
const int ACI_EN_AZ = 0;
const int ACI_EN_COK = 180;
const int BASLANGIC_ACISI = 90;

WebServer sunucu(80);
Servo servo;
int aci = BASLANGIC_ACISI;

// Telefonda açılan sayfa. Kaydırıcı bırakılınca fetch() ile /aci?deger=... gönderir.
const char SAYFA[] PROGMEM = R"HTML(<!doctype html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>ESP32 Servo</title>
<style>
body{font-family:sans-serif;text-align:center;padding:20px}
input[type=range]{width:90%;max-width:360px}
#aci{font-size:48px;font-weight:bold;margin:12px}
button{font-size:18px;margin:4px;padding:8px 16px;border-radius:8px}
</style></head><body>
<h1>Servo kontrolü</h1>
<div id="aci">-- °</div>
<input id="kaydir" type="range" min="0" max="180" value="90">
<p><button onclick="gonder(0)">0°</button><button onclick="gonder(90)">90°</button><button onclick="gonder(180)">180°</button></p>
<p id="durum">Bağlanıyor...</p>
<script>
var k = document.getElementById('kaydir');
var d = document.getElementById('durum');
var goster = function (a) { document.getElementById('aci').textContent = a + ' °'; k.value = a; };
var gonder = function (a) {
  d.textContent = 'Gönderiliyor...';
  fetch('/aci?deger=' + a).then(function (r) { return r.text(); }).then(function (t) {
    goster(t);
    d.textContent = 'Servo şu an ' + t + ' derecede.';
  }).catch(function () { d.textContent = 'ESP32 cevap vermedi.'; });
};
k.oninput = function () { document.getElementById('aci').textContent = k.value + ' °'; };
k.onchange = function () { gonder(k.value); };
fetch('/durum').then(function (r) { return r.text(); }).then(function (t) { goster(t); d.textContent = 'Hazır.'; });
</script></body></html>)HTML";

void anaSayfa() {
  sunucu.send(200, "text/html", SAYFA);
}

// /aci?deger=120 : servoyu 120 dereceye çevirir, yeni açıyı döndürür.
void aciAyarla() {
  if (!sunucu.hasArg("deger")) {
    sunucu.send(400, "text/plain", "deger eksik");
    return;
  }
  aci = constrain(sunucu.arg("deger").toInt(), ACI_EN_AZ, ACI_EN_COK);
  servo.write(aci);
  Serial.printf("Yeni aci: %d derece\n", aci);
  sunucu.send(200, "text/plain", String(aci));
}

// /durum : servonun şu anki açısı.
void durum() {
  sunucu.send(200, "text/plain", String(aci));
}

void setup() {
  Serial.begin(115200);
  servo.setPeriodHertz(50);              // SG90: 50 Hz
  servo.attach(SERVO_PIN, 500, 2400);    // 0-180 derece için darbe aralığı (mikrosaniye)
  servo.write(aci);

  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  Serial.print("Wi-Fi'ye baglaniyor");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Baglandi. Tarayicida ac: http://");
  Serial.println(WiFi.localIP());

  sunucu.on("/", anaSayfa);
  sunucu.on("/aci", aciAyarla);
  sunucu.on("/durum", durum);
  sunucu.begin();
}

void loop() {
  sunucu.handleClient();
}
